package bayes4s

import bayes4s.testkit.Approx
import cats.syntax.all.*
import java.time.YearMonth
import weaver.SimpleIOSuite

/** Three groups fitted together, and two rate components asked about the same data.
  *
  * Two of the phase's criteria, both of them fits and therefore both slow: the hyperparameters
  * have to be recovered with R-hat below 1.01, and a series generated by a random walk must not
  * yield a trend when a trend component is fitted to it.
  *
  * The second is a comparison of two components rather than a test of one. `LocalLevel` has no
  * trend to report, so the question is whether `Ar1Trend`, given the same series, puts zero inside
  * its trend's interval. If it did not, a walk's wandering would be being read as direction —
  * which is the classic mistake, and the reason the plan asks for this check.
  */
object MultiGroupFitSlowSuite extends SimpleIOSuite with Approx:

  private val months = 14
  private val maxLag = 4
  private val groups = 3
  private val t = IArray.tabulate(months)(m => (m - (months - 1) / 2.0) / months)
  private val visible = ReportingTriangle.rightCensored(months, maxLag + 1, current = months)
  private val settings = RunSettings(chains = 2, warmup = 700, samples = 1200)

  /** Three groups around a common level and trend, with a shared wobble. */
  private val truth = HierarchicalAr1Params[Double](
    muA = IArray(3.0),
    muB = IArray(0.5),
    sigmaA = 0.4,
    sigmaB = 0.15,
    aRaw = IArray(1.0, -0.5, 0.2),
    bRaw = IArray(-0.5, 1.0, 0.0),
    phi = 0.5,
    tau = 0.15,
    eps = IArray.tabulate(months)(m => math.sin(m * 0.8))
  )
  private val delayTruth = GroupedDelayParams[Double](
    cut0 = 0.4,
    increments = IArray(0.7, 0.5, 0.4),
    beta = 0.3,
    delta = IArray(0.0, 0.6, -0.6),
    sigmaCut = 0.5
  )

  private val rate = Ar1TrendHierarchical(IArray.fill(groups)(0))
  private val delay = OrderedLogitDriftByGroup()

  private val blank =
    DelayCountData
      .of(
        t,
        IArray.tabulate(groups)(_ => IArray.tabulate(months)(_ => IArray.fill(maxLag + 1)(0))),
        visible
      )
      .toOption
      .get

  private val generative = DelayCountModel.generative(rate, delay, blank)
  private val parameters = DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double](truth, delayTruth)
  private val observed =
    generative.generative.simulateData[Rand](parameters).runA(Seed(20261107L)).value
  private val model = DelayCountModel(rate, delay, observed)

  test("the fit recovers the hyperparameters and mixes while doing it") {
    // The criteria of 8.2: recovery green, and R-hat below 1.01 on fictional data. Both are
    // asserted on the hyperparameters, which are what a multilevel fit is actually about — the
    // group effects are shrunk by construction and recovering them is a weaker claim.
    cats.effect.IO {
      Mcmc.runNuts(model, settings).runA(Seed(4711L)).value match
        case Left(error) => failure(error.message)
        case Right(chains) =>
          val samples = chains.flatMap(_.draws.map(q => Model.constrain(model, q)))
          def summary(f: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double] => Double) =
            val values = IArray.from(samples.map(f))
            val n = values.length
            val mean = (0 until n).foldLeft(0.0)((s, i) => s + values(i)) / n
            val sd = math.sqrt(
              (0 until n).foldLeft(0.0)((s, i) => s + math.pow(values(i) - mean, 2.0)) / (n - 1.0)
            )
            (mean, sd)
          def rhatOf(f: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double] => Double) =
            Convergence.rhatRank(
              IArray.from(
                chains.map(chain =>
                  IArray.from(chain.draws.map(q => f(Model.constrain(model, q))))
                )
              )
            )
          val wanted = List(
            ("muA", (p: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double]) => p.rate.muA(0), truth.muA(0)),
            ("muB", (p: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double]) => p.rate.muB(0), truth.muB(0)),
            ("cut0", (p: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double]) => p.delay.cut0, delayTruth.cut0),
            ("beta", (p: DelayCountParams[HierarchicalAr1Params, GroupedDelayParams, Double]) => p.delay.beta, delayTruth.beta)
          )
          val recovery = wanted.map { case (name, f, value) =>
            val (mean, sd) = summary(f)
            check(
              math.abs(mean - value) <= 4.0 * sd,
              f"$name: the posterior is $mean%.4f +/- $sd%.4f against a true $value%.4f"
            )
          }
          val mixing = wanted.map { case (name, f, _) =>
            val rhat = rhatOf(f)
            check(rhat < 1.01, f"$name: R-hat is $rhat%.4f")
          }
          recovery.reduce(_.and(_)).and(mixing.reduce(_.and(_)))
    }
  }

  /** The criterion of 8.2: a local level fitted to trendless data finds no trend. */
  test("on data with no trend, the trend component's interval contains zero") {
    // Data simulated from a local level: a random walk, no trend anywhere in it. Then two fits of
    // the same data — `LocalLevel`, which has no trend to find, and `Ar1Trend`, which does. The
    // second must report a trend whose interval contains zero; if it reported a trend, the walk's
    // wandering would be being read as direction, which is the classic mistake.
    val walkTruth = LocalLevelParams[Double](
      level0 = IArray(3.2),
      sigma = 0.12,
      eps = IArray.tabulate(months)(m => math.cos(m * 1.1))
    )
    val flatBlank = DelayCountData.blank(months, maxLag, t, visible).toOption.get
    val walkGenerative = DelayCountModel.generative(LocalLevel(), OrderedLogitDrift(), flatBlank)
    val walkParams = DelayCountParams[LocalLevelParams, OrderedLogitDriftParams, Double](
      walkTruth,
      OrderedLogitDriftParams(0.5, IArray(0.7, 0.5, 0.4), 0.0)
    )
    val walkData =
      walkGenerative.generative.simulateData[Rand](walkParams).runA(Seed(515L)).value
    val withTrend = DelayCountModel(Ar1Trend(), OrderedLogitDrift(), walkData)
    val withWalk = DelayCountModel(LocalLevel(), OrderedLogitDrift(), walkData)
    cats.effect.IO {
      (
        Mcmc.runNuts(withTrend, settings).runA(Seed(8L)).value,
        Mcmc.runNuts(withWalk, settings).runA(Seed(9L)).value
      ) match
        case (Left(error), _) => failure(s"the trend fit: ${error.message}")
        case (_, Left(error)) => failure(s"the walk fit: ${error.message}")
        case (Right(trendChains), Right(walkChains)) =>
          val trends = IArray.from(
            trendChains.flatMap(_.draws.map(q => Model.constrain(withTrend, q).rate.b(0)))
          )
          val low = Quantile.quantile(trends, 0.05)
          val high = Quantile.quantile(trends, 0.95)
          val walkSteps = IArray.from(
            walkChains.flatMap(_.draws.map(q => Model.constrain(withWalk, q).rate.sigma))
          )
          check(
            low <= 0.0 && high >= 0.0,
            f"the trend's 90 %% interval is ($low%.4f, $high%.4f) and excludes zero"
          )
            // The walk, meanwhile, finds the wandering it was given: a step size well above zero.
            .and(
              check(
                Quantile.quantile(walkSteps, 0.05) > 0.01,
                f"the walk's step size is ${Quantile.quantile(walkSteps, 0.05)}%.4f at the 5th " +
                  "percentile, so it did not notice the wandering"
              )
            )
    }
  }
